syntax:
```c++
template <std::size_t N>
struct Factorial {
  static constexpr std::size_t value = N * Factorial<N - 1>::value;
};

template <>
struct Factorial<0> {
  static constexpr std::size_t value = 1;
};

int main() {
  constexpr std::size_t result = Factorial<5>::value; // Computed at compile time
  std::cout << result << std::endl; // Prints 120
  return 0;
}
```

code_example:
#include <iostream>
#include <cstdint>
template <std::size_t N>
struct Fibonacci {
  static constexpr uint64_t value = Fibonacci<N - 1>::value + Fibonacci<N - 2>::value;
};

template <>
struct Fibonacci<0> {
  static constexpr uint64_t value = 0;
};

template <>
struct Fibonacci<1> {
  static constexpr uint64_t value = 1;
};

int main() {
  constexpr uint64_t fib10 = Fibonacci<10>::value;
  std::cout << "Fibonacci(10) = " << fib10 << std::endl;
  return 0;
}
